function ActivityCakeShopDrawItemCell:RefreshItemShow(data)
    self.data = data
    self:RefreshShow()
end

function ActivityCakeShopDrawItemCell:RefreshShow()
    ---@type GoodNodeMB
    local goodEnv = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    local goodsId = self.data.rewards[1].goodsId
    goodEnv:Reload({
        goodsId = goodsId,
        text = string.format("x%d", self.data.rewards[1].num),
        isShowNo = true
    })

    goodEnv:SetClickCallback(function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end
    end)

    if self.data.stock < 0 then
        CfUtils.FillText(self.TextNumber,localize("无限"))
        goodEnv:SetSanXingGainShow(false)
    else
        CfUtils.FillText(self.TextNumber,self.data.currentStock)
        goodEnv:SetSanXingGainShow(checkNumber(self.data.currentStock) <= 0)
    end
end

function ActivityCakeShopDrawItemCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCakeShopDrawItemCell